operation.add:
{% if route|slice(0, 15) == 'product/product' %}
<script>
(function(){
var loaded=false;
function loadRecaptcha(){if(loaded||window.grecaptcha||document.querySelector('script[data-wdh-recaptcha]'))return;loaded=true;var s=document.createElement('script');s.src='https://www.google.com/recaptcha/api.js';s.async=true;s.defer=true;s.setAttribute('data-wdh-recaptcha','1');document.head.appendChild(s);}
var tab=document.querySelector('a[href="#tab-review"]');
if(tab){tab.addEventListener('click',loadRecaptcha,{once:true});}
if(location.hash==='#tab-review'){loadRecaptcha();}
})();
</script>
{% else %}
<script src="//www.google.com/recaptcha/api.js" type="text/javascript"></script>
{% endif %}
